import { actionHash } from "./hash"
import { cloneDefined, deepFreeze } from "./freeze"
import type { Actor, ApprovalStatus, GuardAction } from "./types"
import { GuardError } from "./types"

/**
 * Stable approval port (API v1).
 * CI Checks Live and any other tool call this. It is not WhatsApp-specific.
 * `kind` on the ticket is the action kind, for example "git.merge".
 */
export type ApprovalTicket = {
  id: string
  accountId: string
  kind: string
  action: GuardAction
  actionHash: string
  rulesetId: string
  rulesetVersion: number
  reasonKey: string
  status: ApprovalStatus
  createdAt: number
  expiresAt: number
  decidedAt?: number
  decidedBy?: string
  consumedAt?: number
}

export type ApprovalRequest = {
  accountId: string
  action: GuardAction
  rulesetId: string
  rulesetVersion: number
  reasonKey: string
  ttlMs: number
  now: number
  id?: string
}

export type ApprovalListQuery = {
  now: number
  status?: ApprovalStatus
  kind?: string
}

export type ApprovalDecisionCommand = {
  accountId: string
  actor: Actor
  id: string
  outcome: "approved" | "rejected"
  now: number
}

export type ApprovalConsumeCommand = {
  accountId: string
  id: string
  action: GuardAction
  now: number
}

export interface ApprovalGate {
  create(request: ApprovalRequest): ApprovalTicket
  get(accountId: string, id: string, now: number): ApprovalTicket | null
  list(accountId: string, query: ApprovalListQuery): readonly ApprovalTicket[]
  decide(command: ApprovalDecisionCommand): ApprovalTicket
  consume(command: ApprovalConsumeCommand): ApprovalTicket
}

function strip<T extends Record<string, unknown>>(value: T): T {
  const out: Record<string, unknown> = {}
  for (const [key, item] of Object.entries(value)) {
    if (item !== undefined) out[key] = item
  }
  return out as T
}

export class MemoryApprovalGate implements ApprovalGate {
  private readonly buckets = new Map<string, Map<string, ApprovalTicket>>()
  private sequence = 0

  constructor(private readonly ids: () => string = () => {
    this.sequence += 1
    return `apr_${this.sequence}`
  }) {}

  create(request: ApprovalRequest): ApprovalTicket {
    if (request.action.accountId !== request.accountId) {
      throw new GuardError("isolation", "Approval account does not match the action account.")
    }
    if (!(request.ttlMs > 0)) throw new GuardError("invalid", "Approval TTL must be greater than zero.")
    this.expireAccount(request.accountId, request.now)
    const hash = actionHash(request.action)
    const existing = this.openFor(request, hash)
    if (existing) return existing
    const id = request.id ?? this.ids()
    if (this.bucket(request.accountId).has(id)) throw new GuardError("invalid", "Approval id already exists in this account.")
    const ticket = this.store({
      id,
      accountId: request.accountId,
      kind: request.action.kind,
      action: cloneDefined(request.action),
      actionHash: hash,
      rulesetId: request.rulesetId,
      rulesetVersion: request.rulesetVersion,
      reasonKey: request.reasonKey,
      status: "pending",
      createdAt: request.now,
      expiresAt: request.now + request.ttlMs,
    })
    return ticket
  }

  get(accountId: string, id: string, now: number): ApprovalTicket | null {
    this.expireAccount(accountId, now)
    return this.bucket(accountId).get(id) ?? null
  }

  list(accountId: string, query: ApprovalListQuery): readonly ApprovalTicket[] {
    this.expireAccount(accountId, query.now)
    return [...this.bucket(accountId).values()]
      .filter((ticket) => (query.status ? ticket.status === query.status : true))
      .filter((ticket) => (query.kind ? ticket.kind === query.kind : true))
      .sort((a, b) => a.createdAt - b.createdAt || a.id.localeCompare(b.id))
  }

  decide(command: ApprovalDecisionCommand): ApprovalTicket {
    if (command.actor.accountId !== command.accountId) {
      throw new GuardError("isolation", "The actor cannot decide an approval for another account.")
    }
    if (command.actor.role !== "approver") {
      throw new GuardError("permission", "Only an approver can approve or reject.")
    }
    this.expireAccount(command.accountId, command.now)
    const ticket = this.must(command.accountId, command.id)
    if (ticket.status === "expired") throw new GuardError("expired", "An expired approval cannot be decided.")
    if (ticket.status !== "pending") throw new GuardError("terminal", "That approval is already decided.")
    return this.store({
      ...ticket,
      status: command.outcome,
      decidedAt: command.now,
      decidedBy: command.actor.id,
    })
  }

  consume(command: ApprovalConsumeCommand): ApprovalTicket {
    if (command.action.accountId !== command.accountId) {
      throw new GuardError("isolation", "Consume account does not match the action account.")
    }
    this.expireAccount(command.accountId, command.now)
    const ticket = this.must(command.accountId, command.id)
    if (ticket.status === "expired") throw new GuardError("expired", "An expired approval cannot be used.")
    if (ticket.status !== "approved") throw new GuardError("terminal", "Only an approved ticket can be consumed.")
    if (ticket.consumedAt !== undefined) throw new GuardError("replay", "That approval was already used.")
    if (ticket.actionHash !== actionHash(command.action)) {
      throw new GuardError("replay", "The action does not match the approved payload.")
    }
    return this.store({ ...ticket, consumedAt: command.now })
  }

  private openFor(request: ApprovalRequest, hash: string) {
    for (const ticket of this.bucket(request.accountId).values()) {
      if (ticket.actionHash !== hash) continue
      if (ticket.rulesetId !== request.rulesetId || ticket.rulesetVersion !== request.rulesetVersion) continue
      if (ticket.status === "pending") return ticket
      if (ticket.status === "approved" && ticket.consumedAt === undefined) return ticket
    }
    return null
  }

  private expireAccount(accountId: string, now: number) {
    for (const ticket of this.bucket(accountId).values()) {
      if ((ticket.status === "pending" || ticket.status === "approved") && now >= ticket.expiresAt) {
        this.store({ ...ticket, status: "expired" })
      }
    }
  }

  private must(accountId: string, id: string) {
    const ticket = this.bucket(accountId).get(id)
    if (!ticket) throw new GuardError("not_found", "No approval with that id exists in this account.")
    return ticket
  }

  private bucket(accountId: string) {
    const found = this.buckets.get(accountId)
    if (found) return found
    const created = new Map<string, ApprovalTicket>()
    this.buckets.set(accountId, created)
    return created
  }

  private store(ticket: ApprovalTicket) {
    const frozen = deepFreeze(strip(cloneDefined(ticket) as unknown as Record<string, unknown>) as unknown as ApprovalTicket)
    this.bucket(ticket.accountId).set(ticket.id, frozen)
    return frozen
  }
}

import type { Condition, ConditionTrace, GuardLocale, Scalar } from "./types"

const BLOCKED_PATH = new Set(["__proto__", "prototype", "constructor"])

export type CondEval = {
  result: "true" | "false" | "missing"
  missingPaths: string[]
  trace: ConditionTrace
}

function unique(paths: string[]) {
  return [...new Set(paths)].sort()
}

export function isBlockedPath(path: string) {
  return path.split(".").some((part) => BLOCKED_PATH.has(part) || part.trim() === "")
}

export function readPath(data: Record<string, unknown>, path: string): { ok: true; value: unknown } | { ok: false } {
  if (!path || isBlockedPath(path)) return { ok: false }
  let current: unknown = data
  for (const part of path.split(".")) {
    if (current === null || typeof current !== "object" || Array.isArray(current)) return { ok: false }
    if (!Object.prototype.hasOwnProperty.call(current, part)) return { ok: false }
    current = (current as Record<string, unknown>)[part]
    if (current === undefined) return { ok: false }
  }
  return { ok: true, value: current }
}

function leaf(op: string, path: string, result: CondEval["result"]): CondEval {
  const missingPaths = result === "missing" ? [path] : []
  return { result, missingPaths, trace: { op, path, result, missingPaths } }
}

function foldText(value: string) {
  return value.normalize("NFKC").replace(/[\u200B-\u200D\uFEFF]/g, "").toLocaleLowerCase("es-MX")
}

function asNumber(value: unknown): number | null {
  if (typeof value !== "number" || Number.isNaN(value)) return null
  return value
}

export function evalCondition(condition: Condition, data: Record<string, unknown>): CondEval {
  if (condition.op === "and" || condition.op === "or") {
    const children = condition.conditions.map((child) => evalCondition(child, data))
    const results = children.map((child) => child.result)
    let result: CondEval["result"]
    if (condition.op === "and") {
      if (results.length === 0) result = "true"
      else if (results.some((item) => item === "false")) result = "false"
      else if (results.some((item) => item === "missing")) result = "missing"
      else result = "true"
    } else if (results.length === 0) result = "false"
    else if (results.some((item) => item === "true")) result = "true"
    else if (results.some((item) => item === "missing")) result = "missing"
    else result = "false"
    const missingPaths = result === "missing" ? unique(children.flatMap((child) => child.missingPaths)) : []
    return {
      result,
      missingPaths,
      trace: { op: condition.op, result, missingPaths, children: children.map((child) => child.trace) },
    }
  }

  if (condition.op === "not") {
    const child = evalCondition(condition.condition, data)
    const result: CondEval["result"] = child.result === "missing" ? "missing" : child.result === "true" ? "false" : "true"
    const missingPaths = result === "missing" ? child.missingPaths : []
    return { result, missingPaths, trace: { op: "not", result, missingPaths, children: [child.trace] } }
  }

  if (!("path" in condition)) {
    return { result: "missing", missingPaths: [], trace: { op: condition.op, result: "missing", missingPaths: [] } }
  }

  if (condition.op === "exists" || condition.op === "missing") {
    const present = readPath(data, condition.path).ok
    const ok = condition.op === "exists" ? present : !present
    return leaf(condition.op, condition.path, ok ? "true" : "false")
  }

  const found = readPath(data, condition.path)
  if (!found.ok) return leaf(condition.op, condition.path, "missing")
  const value = found.value

  if (condition.op === "eq") return leaf(condition.op, condition.path, Object.is(value, condition.value) ? "true" : "false")
  if (condition.op === "neq") return leaf(condition.op, condition.path, Object.is(value, condition.value) ? "false" : "true")

  if (condition.op === "gt" || condition.op === "gte" || condition.op === "lt" || condition.op === "lte") {
    const number = asNumber(value)
    if (number === null) return leaf(condition.op, condition.path, "missing")
    const ok =
      condition.op === "gt"
        ? number > condition.value
        : condition.op === "gte"
          ? number >= condition.value
          : condition.op === "lt"
            ? number < condition.value
            : number <= condition.value
    return leaf(condition.op, condition.path, ok ? "true" : "false")
  }

  if (condition.op === "in") {
    const hit = condition.values.some((item) => Object.is(item, value as Scalar))
    return leaf(condition.op, condition.path, hit ? "true" : "false")
  }

  if (condition.op === "includes" || condition.op === "text_includes") {
    if (condition.op === "includes") {
      if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) return leaf(condition.op, condition.path, "missing")
      return leaf(condition.op, condition.path, value.includes(condition.value) ? "true" : "false")
    }
    if (typeof value !== "string" || !condition.value) return leaf(condition.op, condition.path, typeof value === "string" ? "false" : "missing")
    const hit = foldText(value).includes(foldText(condition.value))
    return leaf(condition.op, condition.path, hit ? "true" : "false")
  }

  return leaf(condition.op, condition.path, "missing")
}

export function actionData(data: Record<string, unknown>, text: string | undefined): Record<string, unknown> {
  if (Object.prototype.hasOwnProperty.call(data, "text") || text === undefined) return data
  return { ...data, text }
}

const OP_ES: Record<string, string> = {
  and: "y",
  or: "o",
  not: "no",
  eq: "es",
  neq: "no es",
  gt: "es mayor que",
  gte: "es al menos",
  lt: "es menor que",
  lte: "es como máximo",
  in: "está en",
  exists: "existe",
  missing: "falta",
  includes: "incluye",
  text_includes: "el texto incluye",
}

const OP_EN: Record<string, string> = {
  and: "and",
  or: "or",
  not: "not",
  eq: "is",
  neq: "is not",
  gt: "is greater than",
  gte: "is at least",
  lt: "is less than",
  lte: "is at most",
  in: "is in",
  exists: "exists",
  missing: "is missing",
  includes: "includes",
  text_includes: "the text includes",
}

function literal(value: unknown) {
  return typeof value === "string" ? value : JSON.stringify(value)
}

export function describeCondition(condition: Condition, locale: GuardLocale): string {
  const word = (locale === "es" ? OP_ES : OP_EN)[condition.op] ?? condition.op
  if (condition.op === "and" || condition.op === "or") {
    if (condition.conditions.length === 0) return locale === "es" ? "siempre" : "always"
    return condition.conditions.map((child) => describeCondition(child, locale)).join(` ${word} `)
  }
  if (condition.op === "not") return `${word} (${describeCondition(condition.condition, locale)})`
  if (condition.op === "exists" || condition.op === "missing") return `${condition.path} ${word}`
  if (condition.op === "in") return `${condition.path} ${word} ${condition.values.map(literal).join(", ")}`
  if (condition.op === "eq" || condition.op === "neq" || condition.op === "includes" || condition.op === "text_includes") {
    return `${condition.path} ${word} ${literal(condition.value)}`
  }
  if (condition.op === "gt" || condition.op === "gte" || condition.op === "lt" || condition.op === "lte") {
    return `${condition.path} ${word} ${condition.value}`
  }
  return word
}

export function blankCondition(op: Condition["op"]): Condition {
  if (op === "and" || op === "or") return { op, conditions: [] }
  if (op === "not") return { op, condition: { op: "exists", path: "topic" } }
  if (op === "eq" || op === "neq") return { op, path: "topic", value: "" }
  if (op === "gt" || op === "gte" || op === "lt" || op === "lte") return { op, path: "stuckCount", value: 0 }
  if (op === "in") return { op, path: "stage", values: [] }
  if (op === "exists" || op === "missing") return { op, path: "topic" }
  return { op, path: "text", value: "" }
}

export function replaceCondition(root: Condition, path: number[], next: Condition): Condition {
  if (path.length === 0) return next
  const [head, ...rest] = path
  if (head === undefined) return root
  if (root.op === "and" || root.op === "or") {
    return {
      ...root,
      conditions: root.conditions.map((child, index) => (index === head ? replaceCondition(child, rest, next) : child)),
    }
  }
  if (root.op === "not" && head === 0) return { ...root, condition: replaceCondition(root.condition, rest, next) }
  return root
}

export function addChildCondition(root: Condition, path: number[], child: Condition = blankCondition("eq")): Condition {
  const target = conditionAt(root, path)
  if (!target) return root
  if (target.op === "and" || target.op === "or") {
    return replaceCondition(root, path, { ...target, conditions: [...target.conditions, child] })
  }
  if (target.op === "not") return root
  const group: Condition = { op: "and", conditions: [target, child] }
  return replaceCondition(root, path, group)
}

export function removeChildCondition(root: Condition, path: number[]): Condition {
  if (path.length === 0) return root
  const parentPath = path.slice(0, -1)
  const index = path[path.length - 1]
  const parent = conditionAt(root, parentPath)
  if (!parent || index === undefined) return root
  if (parent.op === "and" || parent.op === "or") {
    return replaceCondition(root, parentPath, {
      ...parent,
      conditions: parent.conditions.filter((_, childIndex) => childIndex !== index),
    })
  }
  return root
}

export function conditionAt(root: Condition, path: number[]): Condition | null {
  let current: Condition = root
  for (const index of path) {
    if (current.op === "and" || current.op === "or") {
      const next = current.conditions[index]
      if (!next) return null
      current = next
      continue
    }
    if (current.op === "not" && index === 0) {
      current = current.condition
      continue
    }
    return null
  }
  return current
}

const BLOCKED = new Set(["__proto__", "prototype", "constructor"])

export type DataRow = { path: string; value: string }

export function encodeDataValue(value: unknown): string {
  if (typeof value === "string") return value
  if (typeof value === "number" || typeof value === "boolean" || value === null) return JSON.stringify(value)
  return JSON.stringify(value)
}

export function parseDataValue(raw: string): unknown {
  if (raw === "true") return true
  if (raw === "false") return false
  if (raw === "null") return null
  if (/^-?\d+(\.\d+)?$/.test(raw)) return Number(raw)
  if (raw.startsWith("[") || raw.startsWith("{")) {
    try {
      return JSON.parse(raw) as unknown
    } catch {
      return raw
    }
  }
  return raw
}

export function flattenData(data: Record<string, unknown>): DataRow[] {
  const rows: DataRow[] = []
  const visit = (value: unknown, path: string) => {
    if (value !== null && typeof value === "object" && !Array.isArray(value)) {
      const keys = Object.keys(value as Record<string, unknown>).sort()
      if (keys.length === 0 && path) rows.push({ path, value: "{}" })
      for (const key of keys) visit((value as Record<string, unknown>)[key], path ? `${path}.${key}` : key)
      return
    }
    if (path) rows.push({ path, value: encodeDataValue(value) })
  }
  visit(data, "")
  return rows
}

export function unflattenData(rows: readonly DataRow[]): Record<string, unknown> {
  const root: Record<string, unknown> = {}
  for (const row of rows) {
    if (!row.path.trim()) continue
    const parts = row.path.split(".")
    if (parts.some((part) => BLOCKED.has(part) || part.trim() === "")) continue
    let cursor: Record<string, unknown> = root
    for (let index = 0; index < parts.length - 1; index += 1) {
      const part = parts[index]!
      const next = cursor[part]
      if (next === null || typeof next !== "object" || Array.isArray(next)) {
        const created: Record<string, unknown> = {}
        cursor[part] = created
        cursor = created
      } else {
        cursor = next as Record<string, unknown>
      }
    }
    const leaf = parts[parts.length - 1]!
    cursor[leaf] = parseDataValue(row.value)
  }
  return root
}

import { actionData, describeCondition, evalCondition } from "./condition"
import type { DecisionKind, Evaluation, GuardAction, GuardLocale, GuardRule, RuleTrace, Ruleset, TerminalDecision } from "./types"
import { GuardError } from "./types"

function kindMatches(kinds: readonly string[], kind: string) {
  return kinds.includes("*") || kinds.includes(kind)
}

function pickDecision(fired: readonly DecisionKind[], missing: boolean): { decision: TerminalDecision; failClosed: boolean } {
  if (fired.includes("block")) return { decision: "block", failClosed: false }
  if (fired.includes("handoff_to_human")) return { decision: "handoff_to_human", failClosed: false }
  if (fired.includes("require_approval")) return { decision: "require_approval", failClosed: missing }
  if (missing) return { decision: "require_approval", failClosed: true }
  return { decision: "allow", failClosed: false }
}

/**
 * Pure, deterministic evaluation.
 * Missing data never resolves to allow: it becomes require_approval (fail-closed)
 * unless a fired block or handoff_to_human already outranks it.
 * A proven false condition does not become missing.
 * log always accumulates and never chooses the decision.
 */
export function evaluateRules(ruleset: Ruleset, action: GuardAction, clock: () => number): Evaluation {
  if (ruleset.accountId !== action.accountId) {
    throw new GuardError("isolation", "The ruleset account does not match the action account.")
  }
  const data = actionData(action.data, action.text)
  const traces: RuleTrace[] = []
  const firedDecisions: DecisionKind[] = []
  const fired: Evaluation["fired"][number][] = []
  const logs: Evaluation["logs"][number][] = []
  const missing = new Set<string>()

  for (const rule of ruleset.rules) {
    if (!rule.enabled || !kindMatches(rule.kinds, action.kind)) {
      traces.push({
        ruleId: rule.id,
        ruleName: rule.name,
        kindMatched: rule.enabled && kindMatches(rule.kinds, action.kind),
        status: "skipped",
        missingPaths: [],
      })
      continue
    }
    const condition = evalCondition(rule.conditions, data)
    if (condition.result === "missing") {
      for (const path of condition.missingPaths) missing.add(path)
      traces.push({
        ruleId: rule.id,
        ruleName: rule.name,
        kindMatched: true,
        status: "missing",
        decision: rule.decision,
        reasonKey: rule.reasonKey,
        missingPaths: condition.missingPaths,
        condition: condition.trace,
      })
      continue
    }
    if (condition.result === "true") {
      firedDecisions.push(rule.decision)
      fired.push({ ruleId: rule.id, decision: rule.decision, reasonKey: rule.reasonKey })
      if (rule.decision === "log") logs.push({ ruleId: rule.id, reasonKey: rule.reasonKey })
      traces.push({
        ruleId: rule.id,
        ruleName: rule.name,
        kindMatched: true,
        status: "fired",
        decision: rule.decision,
        reasonKey: rule.reasonKey,
        missingPaths: [],
        condition: condition.trace,
      })
      continue
    }
    traces.push({
      ruleId: rule.id,
      ruleName: rule.name,
      kindMatched: true,
      status: "matched_false",
      decision: rule.decision,
      reasonKey: rule.reasonKey,
      missingPaths: [],
      condition: condition.trace,
    })
  }

  const picked = pickDecision(firedDecisions, missing.size > 0)
  return {
    accountId: action.accountId,
    kind: action.kind,
    rulesetId: ruleset.id,
    rulesetVersion: ruleset.version,
    decision: picked.decision,
    failClosed: picked.failClosed,
    fired,
    logs,
    missingPaths: [...missing].sort(),
    traces,
    evaluatedAt: clock(),
  }
}

export function describeRule(rule: GuardRule, locale: GuardLocale): string {
  const kinds = rule.kinds.join(", ")
  const conditions = describeCondition(rule.conditions, locale)
  if (locale === "es") return `Cuando ${kinds}. Si ${conditions}. Entonces ${rule.decision}.`
  return `When ${kinds}. If ${conditions}. Then ${rule.decision}.`
}

export function deepFreeze<T>(value: T): T {
  if (value === null || typeof value !== "object") return value
  if (Object.isFrozen(value)) return value
  for (const key of Object.keys(value as object)) {
    deepFreeze((value as Record<string, unknown>)[key])
  }
  return Object.freeze(value)
}

export function cloneDefined<T>(value: T): T {
  return structuredClone(value)
}

import type { ApprovalGate, ApprovalTicket } from "./approval-gate"
import type { AuditLog } from "./audit-log"
import { evaluateRules } from "./evaluate"
import { actionHash } from "./hash"
import type { Evaluation, GuardAction, Ruleset, TerminalDecision } from "./types"
import { DEFAULT_APPROVAL_TTL_MS, GuardError, REASON } from "./types"

export type GuardDeps = {
  ruleset: Ruleset | null
  gate: ApprovalGate
  audit: AuditLog
  clock: () => number
  nextAuditId: () => string
  agentResponse?: string
}

export type GuardOutcome = {
  decision: TerminalDecision
  evaluation: Evaluation | null
  approval: ApprovalTicket | null
  failClosed: boolean
}

function ttlFor(evaluation: Evaluation, ruleset: Ruleset) {
  const ids = new Set(evaluation.fired.filter((rule) => rule.decision === "require_approval").map((rule) => rule.ruleId))
  const ttls = ruleset.rules.filter((rule) => ids.has(rule.id) && rule.approvalTtlMs !== undefined).map((rule) => rule.approvalTtlMs!)
  if (ttls.length === 0) return DEFAULT_APPROVAL_TTL_MS
  return Math.min(...ttls)
}

function reasonFor(evaluation: Evaluation) {
  const approval = evaluation.fired.find((rule) => rule.decision === "require_approval")
  if (approval) return approval.reasonKey
  if (evaluation.failClosed) return REASON.missing
  return REASON.none
}

/**
 * Hook for an agent loop, before the action runs.
 * A block or a handoff is final. require_approval opens an ApprovalGate ticket.
 * An approved, unconsumed, unexpired ticket for the same action hash and the
 * same ruleset version is consumed once and the outcome becomes allow.
 */
export function guardAction(deps: GuardDeps, action: GuardAction): GuardOutcome {
  const now = deps.clock()
  if (deps.ruleset && deps.ruleset.accountId !== action.accountId) {
    throw new GuardError("isolation", "Refusing to evaluate an action with another account's ruleset.")
  }
  if (!deps.ruleset) {
    const approval = deps.gate.create({
      accountId: action.accountId,
      action,
      rulesetId: "none",
      rulesetVersion: 0,
      reasonKey: REASON.noRuleset,
      ttlMs: DEFAULT_APPROVAL_TTL_MS,
      now,
    })
    deps.audit.append({
      id: deps.nextAuditId(),
      accountId: action.accountId,
      rulesetId: "none",
      rulesetVersion: 0,
      ruleIds: [],
      input: action,
      decision: "require_approval",
      failClosed: true,
      createdAt: now,
      ...(deps.agentResponse !== undefined ? { agentResponse: deps.agentResponse } : {}),
    })
    return { decision: "require_approval", evaluation: null, approval, failClosed: true }
  }

  const evaluation = evaluateRules(deps.ruleset, action, () => now)
  if (evaluation.decision === "block" || evaluation.decision === "handoff_to_human") {
    deps.audit.append(auditFrom(deps, evaluation, action, now))
    return { decision: evaluation.decision, evaluation, approval: null, failClosed: false }
  }

  if (evaluation.decision === "require_approval") {
    const hash = actionHash(action)
    const releasable = deps.gate.list(action.accountId, { now, status: "approved", kind: action.kind }).find((ticket) => {
      return (
        ticket.consumedAt === undefined &&
        ticket.actionHash === hash &&
        ticket.rulesetId === deps.ruleset!.id &&
        ticket.rulesetVersion === deps.ruleset!.version
      )
    })
    if (releasable?.decidedBy) {
      const spent = deps.gate.consume({ accountId: action.accountId, id: releasable.id, action, now })
      deps.audit.append({
        ...auditFrom(deps, evaluation, action, now),
        decision: "allow",
        approver: releasable.decidedBy,
      })
      return { decision: "allow", evaluation, approval: spent, failClosed: false }
    }
    const approval = deps.gate.create({
      accountId: action.accountId,
      action,
      rulesetId: deps.ruleset.id,
      rulesetVersion: deps.ruleset.version,
      reasonKey: reasonFor(evaluation),
      ttlMs: ttlFor(evaluation, deps.ruleset),
      now,
    })
    deps.audit.append(auditFrom(deps, evaluation, action, now))
    return { decision: "require_approval", evaluation, approval, failClosed: evaluation.failClosed }
  }

  deps.audit.append(auditFrom(deps, evaluation, action, now))
  return { decision: "allow", evaluation, approval: null, failClosed: false }
}

function auditFrom(deps: GuardDeps, evaluation: Evaluation, action: GuardAction, now: number) {
  return {
    id: deps.nextAuditId(),
    accountId: action.accountId,
    rulesetId: evaluation.rulesetId,
    rulesetVersion: evaluation.rulesetVersion,
    ruleIds: evaluation.fired.map((rule) => rule.ruleId),
    input: action,
    decision: evaluation.decision,
    failClosed: evaluation.failClosed,
    createdAt: now,
    ...(deps.agentResponse !== undefined ? { agentResponse: deps.agentResponse } : {}),
  }
}

import type { GuardAction } from "./types"

function stableStringify(value: unknown): string {
  if (value === undefined) return "null"
  if (value === null || typeof value !== "object") return JSON.stringify(value)
  if (Array.isArray(value)) return `[${value.map((item) => stableStringify(item)).join(",")}]`
  const record = value as Record<string, unknown>
  const keys = Object.keys(record).sort()
  return `{${keys.map((key) => `${JSON.stringify(key)}:${stableStringify(record[key])}`).join(",")}}`
}

/** Deterministic hash of an action. Same payload, same hash. Not a secret. */
export function actionHash(action: GuardAction): string {
  const body: Record<string, unknown> = {
    accountId: action.accountId,
    kind: action.kind,
    data: action.data,
  }
  if (action.text !== undefined) body.text = action.text
  const json = stableStringify(body)
  let hash = 2166136261
  for (let index = 0; index < json.length; index += 1) {
    hash ^= json.charCodeAt(index)
    hash = Math.imul(hash, 16777619)
  }
  return (hash >>> 0).toString(16).padStart(8, "0")
}

export function stableStringifyValue(value: unknown): string {
  return stableStringify(value)
}

