import { cloneDefined, deepFreeze } from "./freeze"
import type { Actor, Ruleset, RulesetDraft, RulesetSummary } from "./types"
import { GuardError } from "./types"

export interface RulesetPort {
  list(actor: Actor): readonly RulesetSummary[]
  get(actor: Actor, rulesetId: string, version: number): Ruleset | null
  active(actor: Actor): Ruleset | null
  /** System read. Returns only that account's active ruleset. */
  activeForAccount(accountId: string): Ruleset | null
  save(actor: Actor, draft: RulesetDraft): Ruleset
  activate(actor: Actor, rulesetId: string, version: number): void
}

type VersionMap = Map<string, Map<number, Ruleset>>

export class MemoryRulesetStore implements RulesetPort {
  private readonly accounts = new Map<string, VersionMap>()
  private readonly activePointer = new Map<string, { id: string; version: number }>()

  list(actor: Actor): readonly RulesetSummary[] {
    const versions = this.accounts.get(actor.accountId)
    if (!versions) return []
    const pointer = this.activePointer.get(actor.accountId)
    const summaries: RulesetSummary[] = []
    for (const [id, history] of versions) {
      const latest = [...history.keys()].sort((a, b) => a - b).at(-1)
      if (latest === undefined) continue
      const ruleset = history.get(latest)
      if (!ruleset) continue
      summaries.push({
        id,
        name: ruleset.name,
        version: latest,
        active: pointer?.id === id && pointer.version === latest,
      })
    }
    return summaries.sort((a, b) => a.id.localeCompare(b.id))
  }

  get(actor: Actor, rulesetId: string, version: number): Ruleset | null {
    return this.accounts.get(actor.accountId)?.get(rulesetId)?.get(version) ?? null
  }

  active(actor: Actor): Ruleset | null {
    return this.activeForAccount(actor.accountId)
  }

  activeForAccount(accountId: string): Ruleset | null {
    const pointer = this.activePointer.get(accountId)
    if (!pointer) return null
    return this.accounts.get(accountId)?.get(pointer.id)?.get(pointer.version) ?? null
  }

  save(actor: Actor, draft: RulesetDraft): Ruleset {
    if (actor.role !== "editor") throw new GuardError("permission", "Only an editor can save a ruleset version.")
    if (actor.accountId !== draft.accountId) {
      throw new GuardError("isolation", "An editor cannot write a ruleset into another account.")
    }
    const history = this.history(draft.accountId, draft.id)
    const nextVersion = ([...history.keys()].sort((a, b) => a - b).at(-1) ?? 0) + 1
    const ruleset = deepFreeze(
      cloneDefined({
        id: draft.id,
        accountId: draft.accountId,
        version: nextVersion,
        name: draft.name,
        rules: draft.rules,
      }),
    )
    history.set(nextVersion, ruleset)
    return ruleset
  }

  activate(actor: Actor, rulesetId: string, version: number): void {
    if (actor.role !== "editor") throw new GuardError("permission", "Only an editor can activate a ruleset.")
    const ruleset = this.accounts.get(actor.accountId)?.get(rulesetId)?.get(version)
    if (!ruleset) throw new GuardError("not_found", "That ruleset version does not exist in this account.")
    this.activePointer.set(actor.accountId, { id: rulesetId, version })
  }

  private history(accountId: string, rulesetId: string) {
    let versions = this.accounts.get(accountId)
    if (!versions) {
      versions = new Map()
      this.accounts.set(accountId, versions)
    }
    let history = versions.get(rulesetId)
    if (!history) {
      history = new Map()
      versions.set(rulesetId, history)
    }
    return history
  }
}

import { isBlockedPath } from "./condition"
import type { Condition, DecisionKind, GuardRule, Ruleset, RulesetDraft, Scalar } from "./types"
import { DECISION_KINDS, GuardError } from "./types"

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value)
}

function isScalar(value: unknown): value is Scalar {
  return value === null || ["string", "number", "boolean"].includes(typeof value)
}

const OPS = ["and", "or", "not", "eq", "neq", "gt", "gte", "lt", "lte", "in", "exists", "missing", "includes", "text_includes"] as const

function isOp(value: string): value is Condition["op"] {
  return (OPS as readonly string[]).includes(value)
}

export function parseCondition(value: unknown, errors: string[], where: string): Condition | null {
  if (!isRecord(value) || typeof value.op !== "string" || !isOp(value.op)) {
    errors.push(`${where} needs a known op`)
    return null
  }
  if (value.op === "and" || value.op === "or") {
    if (!Array.isArray(value.conditions)) {
      errors.push(`${where}.conditions must be a list`)
      return null
    }
    const conditions: Condition[] = []
    value.conditions.forEach((child, index) => {
      const parsed = parseCondition(child, errors, `${where}.conditions[${index}]`)
      if (parsed) conditions.push(parsed)
    })
    return { op: value.op, conditions }
  }
  if (value.op === "not") {
    const condition = parseCondition(value.condition, errors, `${where}.condition`)
    return condition ? { op: "not", condition } : null
  }
  if (typeof value.path !== "string" || isBlockedPath(value.path)) {
    errors.push(`${where}.path is empty or unsafe`)
    return null
  }
  if (value.op === "exists" || value.op === "missing") return { op: value.op, path: value.path }
  if (value.op === "in") {
    if (!Array.isArray(value.values) || value.values.some((item) => !isScalar(item))) {
      errors.push(`${where}.values must be scalars`)
      return null
    }
    return { op: "in", path: value.path, values: value.values }
  }
  if (value.op === "gt" || value.op === "gte" || value.op === "lt" || value.op === "lte") {
    if (typeof value.value !== "number" || Number.isNaN(value.value)) {
      errors.push(`${where}.value must be a number`)
      return null
    }
    return { op: value.op, path: value.path, value: value.value }
  }
  if (value.op === "includes" || value.op === "text_includes") {
    if (typeof value.value !== "string") {
      errors.push(`${where}.value must be a string`)
      return null
    }
    return { op: value.op, path: value.path, value: value.value }
  }
  if (value.op !== "eq" && value.op !== "neq") {
    errors.push(`${where} could not be parsed`)
    return null
  }
  if (!isScalar(value.value)) {
    errors.push(`${where}.value must be a scalar`)
    return null
  }
  return { op: value.op, path: value.path, value: value.value }
}

export function parseRule(value: unknown, errors: string[], where: string): GuardRule | null {
  if (!isRecord(value)) {
    errors.push(`${where} must be an object`)
    return null
  }
  if (typeof value.id !== "string" || typeof value.name !== "string" || typeof value.reasonKey !== "string") {
    errors.push(`${where} needs id, name, and reasonKey`)
    return null
  }
  if (!Array.isArray(value.kinds) || value.kinds.some((kind) => typeof kind !== "string" || kind.length === 0)) {
    errors.push(`${where}.kinds must be non-empty strings`)
    return null
  }
  if (typeof value.enabled !== "boolean") {
    errors.push(`${where}.enabled must be boolean`)
    return null
  }
  if (typeof value.decision !== "string" || !DECISION_KINDS.includes(value.decision as DecisionKind)) {
    errors.push(`${where}.decision is unknown`)
    return null
  }
  const conditions = parseCondition(value.conditions, errors, `${where}.conditions`)
  if (!conditions) return null
  if (value.decision === "allow" && conditions.op === "and" && conditions.conditions.length === 0) {
    errors.push(`${where} allow cannot be unconditional`)
    return null
  }
  const rule: GuardRule = {
    id: value.id,
    name: value.name,
    enabled: value.enabled,
    kinds: [...value.kinds],
    conditions,
    decision: value.decision as DecisionKind,
    reasonKey: value.reasonKey,
  }
  if (value.approvalTtlMs !== undefined) {
    if (typeof value.approvalTtlMs !== "number" || value.approvalTtlMs <= 0) {
      errors.push(`${where}.approvalTtlMs must be a positive number`)
      return null
    }
    rule.approvalTtlMs = value.approvalTtlMs
  }
  return rule
}

export function parseRuleset(value: unknown): { ok: true; ruleset: Ruleset } | { ok: false; errors: string[] } {
  const errors: string[] = []
  if (!isRecord(value)) return { ok: false, errors: ["ruleset must be an object"] }
  if (typeof value.id !== "string" || typeof value.accountId !== "string" || typeof value.name !== "string") {
    errors.push("ruleset needs id, accountId, and name")
  }
  if (typeof value.version !== "number" || !Number.isInteger(value.version) || value.version < 1) {
    errors.push("version must be an integer >= 1")
  }
  if (!Array.isArray(value.rules)) errors.push("rules must be a list")
  const rules: GuardRule[] = []
  if (Array.isArray(value.rules)) {
    value.rules.forEach((rule, index) => {
      const parsed = parseRule(rule, errors, `rules[${index}]`)
      if (parsed) rules.push(parsed)
    })
  }
  if (errors.length || typeof value.id !== "string" || typeof value.accountId !== "string" || typeof value.name !== "string" || typeof value.version !== "number") {
    return { ok: false, errors }
  }
  return { ok: true, ruleset: { id: value.id, accountId: value.accountId, version: value.version, name: value.name, rules } }
}

export function parseDraft(value: unknown): RulesetDraft {
  const parsed = parseRuleset({ ...(isRecord(value) ? value : {}), version: 1 })
  if (!parsed.ok) throw new GuardError("invalid", parsed.errors.join("; "))
  return { id: parsed.ruleset.id, accountId: parsed.ruleset.accountId, name: parsed.ruleset.name, rules: parsed.ruleset.rules }
}

import type { GuardAction } from "./types"
import { REASON } from "./types"
import { WHATSAPP_KINDS, SYNTHETIC_ACCOUNT, SYNTHETIC_PHONE } from "./preset"

/** Example CRM webhook body. Not a Vambe or n8n contract. No URL and no secret. */
export type ExampleCrmWebhook = {
  accountId: string
  kind: string
  message?: { text?: string; to?: string }
  crm?: {
    stage?: string
    topic?: string
    contactInitiated?: boolean
    stuckCount?: number
    documentType?: string
    discountRequested?: boolean
    offerKind?: string
    offerValidated?: boolean
    requestedSecrets?: string[]
    intent?: string
    mentions?: string[]
    requestedHuman?: boolean
    direction?: string
  }
}

const KINDS = new Set<string>(Object.values(WHATSAPP_KINDS))

/**
 * Maps a fictional webhook into a guard action.
 * Omitted CRM fields stay omitted so the engine can fail closed.
 */
export function mapExampleCrmWebhook(body: ExampleCrmWebhook): GuardAction {
  if (!KINDS.has(body.kind) && body.kind !== "git.merge") {
    throw new Error(`Example mapper does not know kind "${body.kind}". Pass a whatsapp.* kind or "git.merge".`)
  }
  const crm = body.crm ?? {}
  const data: Record<string, unknown> = {}
  if (crm.stage !== undefined) data.stage = crm.stage
  if (crm.topic !== undefined) data.topic = crm.topic
  if (crm.contactInitiated !== undefined) data.contactInitiated = crm.contactInitiated
  if (crm.stuckCount !== undefined) data.stuckCount = crm.stuckCount
  if (crm.documentType !== undefined) data.documentType = crm.documentType
  if (crm.discountRequested !== undefined) data.discountRequested = crm.discountRequested
  if (crm.requestedSecrets !== undefined) data.requestedSecrets = crm.requestedSecrets
  if (crm.intent !== undefined) data.intent = crm.intent
  if (crm.mentions !== undefined) data.mentions = crm.mentions
  if (crm.requestedHuman !== undefined) data.requestedHuman = crm.requestedHuman
  if (crm.direction !== undefined) data.direction = crm.direction
  if (body.message?.to !== undefined) data.destinationPhone = body.message.to
  if (crm.offerKind !== undefined || crm.offerValidated !== undefined) {
    data.offer = {
      ...(crm.offerKind !== undefined ? { kind: crm.offerKind } : {}),
      ...(crm.offerValidated !== undefined ? { validated: crm.offerValidated } : {}),
    }
  }
  if (body.kind === "git.merge") {
    data.repository = "ejemplo/demo"
    data.pullRequest = 0
  }
  return {
    accountId: body.accountId || SYNTHETIC_ACCOUNT,
    kind: body.kind,
    data,
    ...(body.message?.text !== undefined ? { text: body.message.text } : {}),
  }
}

export function syntheticGitMerge(accountId = SYNTHETIC_ACCOUNT): GuardAction {
  return {
    accountId,
    kind: "git.merge",
    data: { repository: "ejemplo/demo", pullRequest: 0, checksGreen: true },
  }
}

